/** The page's own game script, run on HTML inside root; env gives it the page's helpers. */
export function run(root, env) {
  const document = { getElementById: (id) => root.querySelector('#' + id), createElement: (t) => globalThis.document.createElement(t) };
  const { APP_LANG, el, cssVar, safeGet, safeSet, SCX } = env;
  let balLangHook = null;
  (function(){
  const levels = [
    { fL:10, dL:2, dR:4, label_en:'Left: 10 N at 2 m · Right distance: 4 m', label_ta:'இடப்புறம்: 10 N, 2 m தூரம் · வலப்புற தூரம்: 4 m' },
    { fL:20, dL:3, dR:2, label_en:'Left: 20 N at 3 m · Right distance: 2 m', label_ta:'இடப்புறம்: 20 N, 3 m தூரம் · வலப்புற தூரம்: 2 m' },
    { fL:8, dL:5, dR:4, label_en:'Left: 8 N at 5 m · Right distance: 4 m', label_ta:'இடப்புறம்: 8 N, 5 m தூரம் · வலப்புற தூரம்: 4 m' },
    { fL:15, dL:2, dR:3, label_en:'Left: 15 N at 2 m · Right distance: 3 m', label_ta:'இடப்புறம்: 15 N, 2 m தூரம் · வலப்புற தூரம்: 3 m' },
    { fL:25, dL:4, dR:5, label_en:'Boss level! Left: 25 N at 4 m · Right distance: 5 m', label_ta:'பாஸ் லெவல்! இடப்புறம்: 25 N, 4 m தூரம் · வலப்புற தூரம்: 5 m' }
  ];
  const levelRow = document.getElementById('balLevelRow');
  const levelDesc = document.getElementById('balLevelDesc');
  const balSvg = document.getElementById('balSvg');
  const guessSlider = document.getElementById('balGuessSlider');
  const guessVal = document.getElementById('balGuessVal');
  const checkBtn = document.getElementById('balCheckBtn');
  const resultEl = document.getElementById('balResult');
  const starsEl = document.getElementById('balStars');

  let curLevel = 0;
  let bestStars = JSON.parse(safeGet('scx_bal_stars') || '[0,0,0,0,0]');

  function correctForce(lv){ return (lv.fL * lv.dL) / lv.dR; }

  function drawScene(tilt){
    balSvg.innerHTML = '';
    const cx=280, cy=90, halfLen=200;
    const rad = (tilt||0) * Math.PI/180;
    const x1 = cx - halfLen*Math.cos(rad), y1 = cy + halfLen*Math.sin(rad);
    const x2 = cx + halfLen*Math.cos(rad), y2 = cy - halfLen*Math.sin(rad);
    balSvg.appendChild(el('polygon',{points:(cx-14)+','+(cy+32)+' '+(cx+14)+','+(cy+32)+' '+cx+','+(cy+8), fill:cssVar('--panel-2'), stroke:cssVar('--border'), 'stroke-width':2}));
    balSvg.appendChild(el('line',{x1:x1,y1:y1,x2:x2,y2:y2, stroke:cssVar('--accent-2'), 'stroke-width':8, 'stroke-linecap':'round'}));
    balSvg.appendChild(el('circle',{cx:x1,cy:y1,r:8,fill:cssVar('--accent')}));
    balSvg.appendChild(el('circle',{cx:x2,cy:y2,r:8,fill:cssVar('--accent-3')}));
  }

  function renderLevelRow(){
    levelRow.innerHTML = '';
    levels.forEach((lv,i)=>{
      const b = document.createElement('div');
      b.className = 'level-btn' + (i===curLevel ? ' active' : '');
      const stars = bestStars[i] || 0;
      b.innerHTML = '<div class="lnum2">'+(i+1)+'</div><div class="lstars">'+('★'.repeat(stars)+'☆'.repeat(3-stars))+'</div>';
      b.addEventListener('click', ()=>{ curLevel = i; loadLevel(); });
      levelRow.appendChild(b);
    });
  }
  function loadLevel(){
    renderLevelRow();
    const lv = levels[curLevel];
    levelDesc.textContent = (APP_LANG==='ta') ? lv.label_ta : lv.label_en;
    resultEl.textContent = ''; resultEl.className = 'game-result';
    starsEl.textContent = '';
    drawScene(0);
  }
  guessSlider.addEventListener('input', ()=>{ guessVal.textContent = guessSlider.value; });

  checkBtn.addEventListener('click', ()=>{
    const lv = levels[curLevel];
    const correct = correctForce(lv);
    const guess = parseFloat(guessSlider.value);
    const err = Math.abs(guess - correct);
    const diff = (guess*lv.dR) - (lv.fL*lv.dL);
    const tilt = Math.max(-18, Math.min(18, diff*0.5));
    drawScene(Math.abs(diff)<0.5 ? 0 : tilt);
    let stars;
    if(err <= 0.5) stars = 3;
    else if(err <= 1.5) stars = 2;
    else if(err <= 3) stars = 1;
    else stars = 0;

    if(stars === 0){
      resultEl.textContent = (APP_LANG==='ta') ? '😅 நல்ல முயற்சி! சரியான விசை = '+correct.toFixed(1)+' N.' : "😅 Nice try! The correct force was "+correct.toFixed(1)+' N.';
      resultEl.className = 'game-result lose';
      SCX.sndWrong();
    } else {
      resultEl.textContent = (APP_LANG==='ta') ? '🎉 சரியான விசை = '+correct.toFixed(1)+' N — சமநிலை!' : '🎉 The correct force was '+correct.toFixed(1)+' N — balanced!';
      resultEl.className = 'game-result win';
    }
    starsEl.textContent = stars>0 ? ('★'.repeat(stars) + '☆'.repeat(3-stars)) : '';

    const prevBest = bestStars[curLevel] || 0;
    if(stars > prevBest){
      bestStars[curLevel] = stars;
      safeSet('scx_bal_stars', JSON.stringify(bestStars));
      if(stars>0) SCX.pushItLevelResult(stars, bestStars.every(s=>s>0));
    } else if(stars>0){
      SCX.sndCorrect();
    }
    renderLevelRow();
  });

  loadLevel();
  balLangHook = function(){ levelDesc.textContent = (APP_LANG==='ta') ? levels[curLevel].label_ta : levels[curLevel].label_en; renderLevelRow(); };
})();
  return { lang: () => balLangHook && balLangHook() };
}
